import { dangerClearCache, fetchQuery } from '@qortex/query-react';

// In your test setup
beforeEach(() => {
  // Clear all cached data before each test
  dangerClearCache();
});

describe('User API', () => {
  it('should fetch user data', async () => {
    // Test user data fetching
    const user = await fetchQuery(['user', '123'], {
      fetcher: () => fetchUser('123')
    });

    expect(user).toBeDefined();
  });

  it('should handle user not found', async () => {
    // Cache is cleared, so this test starts fresh
    try {
      await fetchQuery(['user', 'nonexistent'], {
        fetcher: () => fetchUser('nonexistent')
      });
    } catch (error) {
      expect(error.message).toBe('User not found');
    }
  });
});

import { dangerClearCache } from '@qortex/query-react';

// Development utility function
function clearAllData() {
  if (process.env.NODE_ENV === 'development') {
    dangerClearCache();
    console.log('All cached data cleared');
  } else {
    console.warn('dangerClearCache should only be used in development');
  }
}

// Add to window for debugging
if (typeof window !== 'undefined' && process.env.NODE_ENV === 'development') {
  (window as any).clearQortexCache = clearAllData;
}

// Usage in browser console:
// clearQortexCache()

import { dangerClearCache, setQueryData } from '@qortex/query-react';

function handleLogout() {
  // Clear all cached data on logout
  // This ensures no user data remains in memory
  dangerClearCache();

  // Redirect to login
  window.location.href = '/login';
}

// Alternative: More targeted approach
function handleLogoutSafe() {
  // Instead of clearing everything, clear specific user data
  setQueryData(['user', 'current'], undefined);
  setQueryData(['user', 'profile'], undefined);
  setQueryData(['user', 'settings'], undefined);

  // Redirect to login
  window.location.href = '/login';
}
